(() => {
  'use strict';

  // ========================================================================
  // 第一章 常量与命名空间
  // ========================================================================
  const VERSION = '3.0.0';
  const GIT_REVISION = '3.0.0-stability-r1-20260722';
  const REPO = 'fkgzs123321/sillytavern';
  const RT_VERSION = '2.0.0';
  const RT_PATH = '/runtime/byd/' + RT_VERSION;
  // CDN @main 多源容错（与圣德 fetchHudBody 同构）
